<script setup lang="ts">
import { computed, ref } from 'vue'
import { RouterLink } from 'vue-router'
import PhotoUpload from '../components/PhotoUpload.vue'
import MeasurementChart from '../components/MeasurementChart.vue'
import { categories, type Category } from '../features/measurements/categories'
import { demoMeasurements, downloadJson, parseMeasurements, type Measurement } from '../features/measurements/data'

const samples = ref<Measurement[]>(demoMeasurements())
const selectedIndex = ref(0)
const sample = computed(() => samples.value[selectedIndex.value])
const importInput = ref<HTMLInputElement>()
const importError = ref('')
const importStatus = ref('')
const importing = ref(false)
const photoVersion = ref(0)
const photos = ref<Array<{ name: string; url: string }>>([])
const activeCategory = ref<Category>('water')
const category = computed(() => categories.find(item => item.id === activeCategory.value)!)
const metrics = computed(() => category.value.metrics.map(metric => ({ ...metric, value: sample.value?.[metric.key] ?? null })))
const primaryValue = computed(() => sample.value?.[category.value.primary.key] ?? null)
const historyPoints = computed(() => (sample.value?.history ?? []).map(point => ({ time: point.time, value: point[category.value.historyKey] })))
function categoryKey(event: KeyboardEvent, index: number) {
  if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return
  event.preventDefault()
  const next = event.key === 'Home' ? 0 : event.key === 'End' ? 2 : (index + (event.key === 'ArrowRight' ? 1 : 2)) % 3
  activeCategory.value = categories[next]!.id
  const buttons = (event.currentTarget as HTMLElement).parentElement?.querySelectorAll<HTMLButtonElement>('[role="tab"]')
  buttons?.[next]?.focus()
}
const metadata = computed(() => sample.value ? [
  ['样本编号', sample.value.id], ['样本名称', sample.value.name], ['作物 / 品种', [sample.value.crop, sample.value.variety].filter(Boolean).join(' / ')],
  ['生育期', sample.value.stage], ['水分处理', sample.value.treatment], ['测量时间', sample.value.measuredAt],
  ['环境温度', unit(sample.value.temperature, '℃', 1)], ['环境湿度', unit(sample.value.humidity, '%', 0)],
  ['鲜重', unit(sample.value.freshWeight, 'g', 3)], ['干重', unit(sample.value.dryWeight, 'g', 3)],
  ['饱和鲜重', unit(sample.value.turgidWeight, 'g', 3)],
] : [])
function unit(value: number | null, suffix: string, precision: number) { return value == null ? '未提供' : `${value.toFixed(precision)} ${suffix}` }
function changeSample() { photoVersion.value++; photos.value = [] }
function showDemo() {
  samples.value = demoMeasurements(); selectedIndex.value = 0; importError.value = ''; importStatus.value = '已载入 3 条示例样本，非真实测量数据。'; changeSample()
}
function clear() { samples.value = []; selectedIndex.value = 0; importStatus.value = ''; importError.value = ''; changeSample() }
async function importFile(event: Event) {
  const input = event.target as HTMLInputElement
  const file = input.files?.[0]
  if (!file || importing.value) return
  importing.value = true; importError.value = ''; importStatus.value = ''
  try {
    if (file.size > 2_000_000) throw new Error('结果文件不能超过 2 MB。')
    const records = parseMeasurements(await file.text(), file.name)
    samples.value = records; selectedIndex.value = 0; changeSample()
    importStatus.value = `已导入 ${records.length} 条样本：${file.name}。请核实原始数据来源。`
  } catch (error) { importError.value = error instanceof Error ? error.message : '文件读取失败，请重新选择。' }
  finally { importing.value = false; input.value = '' }
}
function downloadTemplate() {
  downloadJson('禾诊-样本格式模板.json', [{
    id: '请填写样本编号', name: '请填写样本名称', crop: '水稻', variety: '', stage: '', treatment: '', measuredAt: '',
    temperature: null, humidity: null, freshWeight: null, dryWeight: null, turgidWeight: null,
    rwc: null, lightLux: null, ppfd: null, sunshineHours: null, soilMoisture: null, soilPh: null, soilEc: null, soilTemperature: null, history: [],
  }])
}
</script>

<template>
  <section class="page-content analysis-page">
    <div class="analysis-heading"><div><h1>把田间观察，变成可读的数据。</h1><p>照片记录与测量结果并排查看，保留每一个值得追踪的变化。</p></div><RouterLink to="/">返回作物诊断 <span>↗</span></RouterLink></div>
    <div class="analysis-toolbar">
      <div class="analysis-file-actions"><input ref="importInput" type="file" accept=".json,.csv,.tsv,.txt" class="measurement-file-input" aria-label="导入样本结果文件" @change="importFile"/><button class="import-button" type="button" :disabled="importing" @click="importInput?.click()"><span>＋</span>{{ importing ? '正在导入…' : '导入测量结果' }}</button><button class="analysis-link-button" type="button" @click="downloadTemplate">下载格式模板</button></div>
      <div class="analysis-secondary-actions"><button type="button" @click="showDemo">载入示例</button><button type="button" :disabled="!samples.length" @click="downloadJson('禾诊-样本测量结果.json', samples)">导出数据</button><button type="button" :disabled="!samples.length" @click="clear">清空</button></div>
    </div>
    <div class="analysis-format-note"><span>JSON / CSV / TSV · 最大 2 MB · 最多 100 条样本</span><span>仅在当前页面保留，离开前可导出；照片用于观察，环境指标请导入测量记录。</span></div>
    <p v-if="importError" class="measurement-error" role="alert">{{ importError }} 原有样本已保留。</p>
    <p v-if="importStatus" class="measurement-status" role="status">{{ importStatus }}</p>

    <div v-if="sample" class="analysis-workspace">
      <header class="sample-toolbar"><div><span class="sample-toolbar-icon">⌁</span><div><h2>样本测量详情</h2><p>用数据辅助观察，不替代田间诊断</p></div></div><label class="sample-selector">当前样本<select v-model.number="selectedIndex" @change="changeSample"><option v-for="(record, index) in samples" :key="index" :value="index">{{ record.id }} · {{ record.name || record.crop || '未命名样本' }}</option></select></label></header>
      <div class="sample-origin-bar" :class="{ 'is-imported': sample.origin === 'imported' }"><span class="origin-mark">{{ sample.origin === 'demo' ? '示例 · 非实测' : '文件导入' }}</span><p>{{ sample.origin === 'demo' ? '下方水分、光照与土壤数据均为示例，不是照片识别结果。' : '按原始文件展示数值；尚未经过仪器或农艺有效性校验。' }}</p></div>
      <div class="sample-overview"><div class="sample-overview-symbol"><svg viewBox="0 0 50 50" fill="none" aria-hidden="true"><path d="M25 44V22M25 30C11 30 8 20 8 11c13 0 17 8 17 19ZM25 25c0-14 7-20 18-20 0 13-5 20-18 20Z" stroke="currentColor" stroke-width="2"/></svg></div><div><span>{{ sample.id }}</span><h3>{{ sample.name || '未命名样本' }}</h3><p>{{ sample.crop || '作物未提供' }}<template v-if="sample.stage"> / {{ sample.stage }}</template><template v-if="sample.treatment"> / {{ sample.treatment }}</template></p></div><div class="sample-overview-note"><i></i> {{ sample.origin === 'demo' ? '可视化演示' : '测量数据已载入' }}<small>数据辅助观察，不代替诊断</small></div></div>

      <div class="analysis-category-switch" role="tablist" aria-label="分析维度"><button v-for="(item, index) in categories" :id="'category-' + item.id" :key="item.id" type="button" role="tab" :aria-selected="activeCategory === item.id" aria-controls="measurement-category-panel" :tabindex="activeCategory === item.id ? 0 : -1" :class="{ active: activeCategory === item.id }" @click="activeCategory = item.id" @keydown="categoryKey($event, index)"><span>{{ item.icon }}</span>{{ item.title }}</button><p>{{ category.summary }}</p></div>
      <div id="measurement-category-panel" role="tabpanel" :aria-labelledby="'category-' + activeCategory">
      <div class="measurement-grid">
        <section class="sample-metadata"><h3>样本信息</h3><dl><div v-for="[label, value] in metadata" :key="label"><dt>{{ label }}</dt><dd>{{ value || '未提供' }}</dd></div></dl></section>
        <section class="water-content"><div class="metric-section-title"><h3>{{ category.primary.name }}</h3><span>{{ category.title }}观察</span></div><div class="rwc-number">{{ primaryValue == null ? '—' : primaryValue.toLocaleString('zh-CN', {minimumFractionDigits: category.primary.precision, maximumFractionDigits: category.primary.precision}) }}<small>{{ category.primary.unit }}</small></div><template v-if="category.primary.unit === '%'"><div class="rwc-track" role="meter" :aria-label="category.primary.name" :aria-valuenow="primaryValue ?? undefined" aria-valuemin="0" aria-valuemax="100" :aria-valuetext="primaryValue == null ? '未提供' : primaryValue + '%'"><span :style="{ width: (primaryValue ?? 0) + '%' }"></span></div><div class="rwc-scale"><span>0</span><span>25</span><span>50</span><span>75</span><span>100%</span></div></template><p>{{ primaryValue == null ? '当前文件尚未提供这一指标，可切换其他观察维度。' : category.primary.note + '；请结合生育阶段、测量方法与田间条件理解。' }}</p><details v-if="activeCategory === 'water'" class="rwc-formula"><summary>相对含水量的计算依据</summary><p>（鲜重 − 干重）÷（饱和鲜重 − 干重）× 100%。仅当三种质量均有效且未提供 RWC 时计算。</p></details><div v-else class="dimension-note">{{ activeCategory === 'light' ? '照度、PPFD 与日照时长是不同指标，不进行相互换算。' : '含水率、pH 和电导率请按原检测方法及单位记录。' }}</div></section>
      </div>

      <div class="measurement-secondary-grid"><section class="environment-metrics-panel"><h3>{{ category.title }}指标</h3><div class="environment-metrics"><article v-for="metric in metrics" :key="metric.key"><div><strong><i></i>{{ metric.name }}</strong><span>{{ metric.unit }}</span></div><p>{{ metric.value == null ? '—' : metric.value.toLocaleString('zh-CN', {minimumFractionDigits: metric.precision, maximumFractionDigits: metric.precision}) }}</p><small>{{ metric.value == null ? '未提供' : metric.note }}</small></article></div><p class="indices-note">指标按导入结果展示，未提供的数值保留为空；不通过照片估算。</p></section><section class="sample-photo-panel"><div class="sample-photo-heading"><h3>样本照片</h3><span>{{ photos.length ? '本次观察记录' : '等待添加' }}</span></div><div v-if="photos[0]" class="sample-photo-preview"><img :src="photos[0].url" :alt="photos[0].name"/><span>{{ photos[0].name }}</span></div><PhotoUpload :key="photoVersion" title="添加观察照片" @change="photos = $event" /></section></div>

      <MeasurementChart :points="historyPoints" :title="category.primary.name" :unit="category.primary.unit" :demo="sample.origin === 'demo'" />
      </div>
      <div class="analysis-bottom-note"><span>✳</span><p>把影像、测量数据与田间经验一起记录，让科学管理更有依据。需要营养诊断时，请返回诊断台补充具体症状。</p></div>
    </div>
    <div v-else class="measurement-empty"><svg viewBox="0 0 80 60" fill="none" aria-hidden="true"><path d="M5 50h70M10 43l15-15 14 9 14-26 17 9" stroke="currentColor" stroke-width="2"/><circle cx="53" cy="11" r="4" fill="currentColor"/></svg><h2>等待你的第一份测量记录</h2><p>导入 JSON、CSV 或 TSV 文件，切换查看样本的水分、光照与土壤记录。</p><button class="import-button" type="button" @click="importInput?.click()">导入测量结果</button><button class="analysis-link-button" type="button" @click="showDemo">先看看示例</button></div>
  </section>
</template>

